// Local admin accounts are the fallback when no OIDC provider is available.
// They always need a password and a TOTP code; both are generated by the CLI,
// so weak or reused passwords cannot be set.

const (
	localPrefix     = "local:"
	maxFailures     = 5
	lockoutDuration = 15 * time.Minute
)

var localNameRe = regexp.MustCompile(`^[a-z][a-z0-9._-]{1,31}$`)

// ---- argon2id ----

const (
	argonTime    = 3
	argonMemory  = 64 * 1024 // KiB
	argonThreads = 2
	argonKeyLen  = 32
)

func hashPassword(pw string) string {
	salt := make([]byte, 16)
	if _, err := rand.Read(salt); err != nil {
		panic(err)
	}
	key := argon2.IDKey([]byte(pw), salt, argonTime, argonMemory, argonThreads, argonKeyLen)
	enc := base64.RawStdEncoding
	return fmt.Sprintf("$argon2id$v=19$m=%d,t=%d,p=%d$%s$%s", argonMemory, argonTime, argonThreads, enc.EncodeToString(salt), enc.EncodeToString(key))
}

func checkPassword(encoded, pw string) bool {
	var m, t uint32
	var p uint8
	parts := strings.Split(encoded, "$")
	if len(parts) != 6 || parts[1] != "argon2id" {
		return false
	}
	if _, err := fmt.Sscanf(parts[3], "m=%d,t=%d,p=%d", &m, &t, &p); err != nil {
		return false
	}
	salt, err1 := base64.RawStdEncoding.DecodeString(parts[4])
	want, err2 := base64.RawStdEncoding.DecodeString(parts[5])
	if err1 != nil || err2 != nil || len(want) == 0 || len(want) > 64 {
		return false
	}
	got := argon2.IDKey([]byte(pw), salt, t, m, p, uint32(len(want))) //nolint:gosec // len(want) is checked to be at most 64
	return subtle.ConstantTimeCompare(got, want) == 1
}

// dummyHash keeps the response time of unknown users equal to known ones.
var dummyHash = hashPassword("limdm-timing-equaliser")

// ---- TOTP (RFC 6238, SHA-1, 6 digits, 30 s) ----

var b32 = base32.StdEncoding.WithPadding(base32.NoPadding)

func newTOTPSecret() string {
	b := make([]byte, 20)
	if _, err := rand.Read(b); err != nil {
		panic(err)
	}
	return b32.EncodeToString(b)
}

func totpCode(secret string, step int64) (string, error) {
	key, err := b32.DecodeString(strings.ToUpper(secret))
	if err != nil {
		return "", err
	}
	mac := hmac.New(sha1.New, key)
	mac.Write(binary.BigEndian.AppendUint64(nil, uint64(step))) //nolint:gosec // time steps are positive
	sum := mac.Sum(nil)
	off := sum[len(sum)-1] & 0x0f
	v := binary.BigEndian.Uint32(sum[off:off+4]) & 0x7fffffff
	return fmt.Sprintf("%06d", v%1_000_000), nil
}

// verifyTOTP accepts the current step ±1 and returns the matched step, which
// must be greater than the last used one so a code cannot be replayed.
func verifyTOTP(secret, code string, now time.Time, lastStep int64) (int64, bool) {
	code = strings.TrimSpace(code)
	if len(code) != 6 {
		return 0, false
	}
	cur := now.Unix() / 30
	for _, step := range []int64{cur - 1, cur, cur + 1} {
		want, err := totpCode(secret, step)
		if err == nil && step > lastStep && subtle.ConstantTimeCompare([]byte(want), []byte(code)) == 1 {
			return step, true
		}
	}
	return 0, false
}

func totpURI(name, secret string) string {
	label := url.PathEscape("LiMDM:" + name)
	return fmt.Sprintf("otpauth://totp/%s?secret=%s&issuer=LiMDM&algorithm=SHA1&digits=6&period=30", label, secret)
}

// ---- per IP rate limit ----

// ponytail: in memory, per instance: with n instances an address gets up to
// n times the budget (docs/high-availability.md). The lockout of local
// accounts lives in the database and counts across instances; move this to
// the database when per instance limits are not enough.
type limiter struct {
	mu    sync.Mutex
	hits  map[string][]time.Time
	swept time.Time
}

// limiterTTL bounds every window in use; keys without a hit inside it are
// dropped, so rotating source addresses cannot grow the map without end.
const limiterTTL = time.Hour

// limiterMaxKeys bounds the keys of throughput limits (devices, API tokens);
// beyond it the least recently used of them are dropped. Failure counters
// (sign in, enrollment, token, SCIM and CRL failures) are never dropped
// before their window ends: dropping them would reset a lockout.
var limiterMaxKeys = 200000

// failureKey reports a key that counts failures (see limiterMaxKeys).
func failureKey(k string) bool {
	for _, p := range []string{"login:", "enroll:", "apifail:", "scim:", "crl:"} {
		if strings.HasPrefix(k, p) {
			return true
		}
	}
	return false
}

// sweep drops idle keys once a minute, then the least recently used
// throughput keys over limiterMaxKeys; called with mu held.
func (l *limiter) sweep(now time.Time) {
	if now.Sub(l.swept) < time.Minute {
		return
	}
	l.swept = now
	type use struct {
		key  string
		last time.Time
	}
	var others []use
	for k, ts := range l.hits {
		switch {
		case len(ts) == 0 || now.Sub(ts[len(ts)-1]) > limiterTTL:
			delete(l.hits, k)
		case !failureKey(k):
			others = append(others, use{k, ts[len(ts)-1]})
		}
	}
	if over := len(others) - limiterMaxKeys; over > 0 {
		slices.SortFunc(others, func(a, b use) int { return a.last.Compare(b.last) })
		for _, u := range others[:over] {
			delete(l.hits, u.key)
		}
	}
}

// rateKey is the client's address for rate limits: IPv6 clients by their
// /64, since every host gets a whole prefix to pick addresses from.
func rateKey(r *http.Request) string {
	ip := clientIP(r)
	if a, err := netip.ParseAddr(ip); err == nil && a.Is6() && !a.Is4In6() {
		p, _ := a.Prefix(64)
		return p.String()
	}
	return ip
}

// over reports whether key reached max hits within window, without counting.
func (l *limiter) over(key string, max int, window time.Duration) bool { //nolint:unparam // every caller uses a 5 minute window today
	l.mu.Lock()
	defer l.mu.Unlock()
	n := 0
	for _, t := range l.hits[key] {
		if time.Since(t) < window {
			n++
		}
	}
	return n >= max
}

func (l *limiter) allow(key string, max int, window time.Duration) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.hits == nil {
		l.hits = map[string][]time.Time{}
	}
	now := time.Now()
	l.sweep(now)
	recent := l.hits[key][:0]
	for _, t := range l.hits[key] {
		if now.Sub(t) < window {
			recent = append(recent, t)
		}
	}
	if len(recent) >= max {
		l.hits[key] = recent
		return false
	}
	l.hits[key] = append(recent, now)
	return true
}

// clientIP returns the peer address. Only a reverse proxy on loopback (the
// supported setup without an own TLS certificate) may name the client via
// X-Forwarded-For; the last entry is the one that proxy appended.
func clientIP(r *http.Request) string {
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		host = r.RemoteAddr
	}
	if trustedPeer(host) {
		// the entry the proxy appended: the last of all header lines (a proxy
		// may add its own line instead of extending the client's)
		if xff := strings.Join(r.Header.Values("X-Forwarded-For"), ","); xff != "" {
			parts := strings.Split(xff, ",")
			if fwd := net.ParseIP(strings.TrimSpace(parts[len(parts)-1])); fwd != nil {
				return fwd.String()
			}
			return "0.0.0.0" // unparsable: never fall back to the always allowed loopback peer
		}
	}
	return host
}

// trustedProxies are load balancers (LIMDM_TRUSTED_PROXIES) whose
// X-Forwarded-For names the client, like a reverse proxy on loopback.
// Set once at startup.
var trustedProxies []netip.Prefix

func trustedPeer(host string) bool {
	a, err := netip.ParseAddr(host)
	if err != nil {
		return false
	}
	a = a.Unmap()
	if a.IsLoopback() {
		return true
	}
	for _, p := range trustedProxies {
		if p.Contains(a) {
			return true
		}
	}
	return false
}

// parseProxies reads a comma separated list of addresses and networks.
func parseProxies(list string) ([]netip.Prefix, error) {
	var out []netip.Prefix
	for _, f := range strings.Split(list, ",") {
		if f = strings.TrimSpace(f); f == "" {
			continue
		}
		if !strings.Contains(f, "/") {
			a, err := netip.ParseAddr(f)
			if err != nil {
				return nil, fmt.Errorf("LIMDM_TRUSTED_PROXIES: %w", err)
			}
			out = append(out, netip.PrefixFrom(a.Unmap(), a.Unmap().BitLen()))
			continue
		}
		p, err := netip.ParsePrefix(f)
		if err != nil {
			return nil, fmt.Errorf("LIMDM_TRUSTED_PROXIES: %w", err)
		}
		out = append(out, p.Masked())
	}
	return out, nil
}

// ---- login handlers ----

const loginCookie = "limdm_login"

func (s *Server) loginPage(w http.ResponseWriter, r *http.Request) {
	s.renderLogin(w, r, "")
}

func (s *Server) renderLogin(w http.ResponseWriter, r *http.Request, msg string) {
	tok := randToken(24)
	// double submit token against login CSRF
	http.SetCookie(w, &http.Cookie{Name: loginCookie, Value: tok, Path: "/login", HttpOnly: true, Secure: true,
		SameSite: http.SameSiteStrictMode, MaxAge: 600})
	s.render(w, r, session{}, "login", map[string]any{"OIDC": s.oidc() != nil, "Local": s.localAllowed(), "LoginCSRF": tok, "Error": msg})
}

func (s *Server) localLogin(w http.ResponseWriter, r *http.Request) {
	if !s.localAllowed() {
		http.NotFound(w, r)
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, 8<<10)
	c, err := r.Cookie(loginCookie)
	if err != nil || !hmac.Equal([]byte(c.Value), []byte(r.FormValue("csrf"))) {
		s.errorPage(w, r, session{}, http.StatusForbidden, "login form expired, reload the page")
		return
	}
	if !s.limit.allow("login:"+rateKey(r), 10, 5*time.Minute) {
		s.errorPage(w, r, session{}, http.StatusTooManyRequests, "too many attempts, try again later")
		return
	}
	name := strings.ToLower(strings.TrimSpace(r.FormValue("username")))
	if !localNameRe.MatchString(name) {
		// never log, query or audit arbitrary input; "(invalid)" cannot be a real account name
		name = "(invalid)"
	}
	role, err := s.checkLocal(r.Context(), name, r.FormValue("password"), r.FormValue("totp"), clientIP(r), rateKey(r))
	if err != nil {
		s.log.Warn("local login failed", "user", name, "remote", clientIP(r), "err", err)
		s.renderLogin(w, r, "Sign in failed.")
		return
	}
	now := time.Now()
	_, gen := s.account(r.Context(), localPrefix+name)
	s.setCookie(w, sessionCookie, s.seal(session{Email: localPrefix + name, Role: role, IAT: now, Last: now, Gen: gen}), maxSession)
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

var errLoginFailed = errors.New("invalid credentials")

// checkLocal verifies password and TOTP in one transaction with a row lock,
// counts failures per account and client network (source, see rateKey),
// locks the account for that source after maxFailures, and audits every
// success and failed attempts within localFailures. A lockout from one
// source leaves the account usable from others, so nobody can keep a break
// glass account locked from the internet; the per source rate limit
// (localLogin) slows guessing before that.
func (s *Server) checkLocal(ctx context.Context, name, password, code, ip, source string) (string, error) {
	var role, hash, secret string
	var lastStep int64
	var failures int
	var lockedUntil *time.Time
	result := "login.local.failed"
	// failed is the audit action of a failure: none beyond the budget (the
	// transaction still commits; the process log has it)
	failed := func() string {
		if !localFailures.take() {
			s.log.Warn("local login failure not audited: more than 30 per minute", "user", name)
			return ""
		}
		return result
	}
	err := s.auditActionFn(ctx, func(tx pgx.Tx) (string, string, string, string, error) {
		var accountLock *time.Time // set by failed checks of a signed in user (profile.go)
		qerr := tx.QueryRow(ctx, `SELECT role, password_hash, totp_secret, totp_last_step, locked_until FROM local_admins WHERE name=$1 AND NOT disabled FOR UPDATE`, name).
			Scan(&role, &hash, &secret, &lastStep, &accountLock)
		if errors.Is(qerr, pgx.ErrNoRows) {
			checkPassword(dummyHash, password)
			return localPrefix + name, failed(), ip, "unknown user", nil
		}
		if qerr != nil {
			return "", "", "", "", qerr
		}
		if qerr := tx.QueryRow(ctx, `SELECT failures, locked_until FROM local_login_failures WHERE name=$1 AND source=$2`, name, source).
			Scan(&failures, &lockedUntil); qerr != nil && !errors.Is(qerr, pgx.ErrNoRows) {
			return "", "", "", "", qerr
		}
		if lockedUntil != nil && time.Now().Before(*lockedUntil) || accountLock != nil && time.Now().Before(*accountLock) {
			checkPassword(dummyHash, password) // same timing as an active account
			return localPrefix + name, failed(), ip, "account locked for this source", nil
		}
		pwOK := checkPassword(hash, password)
		step, totpOK := verifyTOTP(secret, code, time.Now(), lastStep)
		usedRecovery := false
		if pwOK && !totpOK {
			ok, rerr := useRecoveryCode(ctx, tx, name, code)
			if rerr != nil {
				return "", "", "", "", rerr
			}
			totpOK, usedRecovery, step = ok, ok, lastStep
		}
		if pwOK && totpOK {
			detail := role
			if usedRecovery {
				detail += ", with a recovery code"
			}
			result = "login"
			_, uerr := tx.Exec(ctx, `UPDATE local_admins SET failures=0, locked_until=NULL, totp_last_step=$2, last_login=now() WHERE name=$1`, name, step)
			if uerr == nil {
				_, uerr = tx.Exec(ctx, `DELETE FROM local_login_failures WHERE name=$1 AND source=$2`, name, source)
			}
			return localPrefix + name, result, ip, detail, uerr
		}
		failures++
		var lock *time.Time
		detail := "wrong password or code"
		if failures >= maxFailures {
			t := time.Now().Add(lockoutDuration)
			lock, failures, detail = &t, 0, "wrong password or code, account locked for this source"
		}
		if _, uerr := tx.Exec(ctx, `INSERT INTO local_login_failures(name, source, failures, locked_until) VALUES ($1,$2,$3,$4)
			ON CONFLICT (name, source) DO UPDATE SET failures=EXCLUDED.failures, locked_until=EXCLUDED.locked_until, updated_at=now()`,
			name, source, failures, lock); uerr != nil {
			return "", "", "", "", uerr
		}
		if lock != nil {
			return localPrefix + name, result, ip, detail, nil // a lockout is always audited
		}
		return localPrefix + name, failed(), ip, detail, nil
	})
	if err != nil {
		return "", err
	}
	if result != "login" {
		return "", errLoginFailed
	}
	return role, nil
}

// auditActionFn runs fn in a transaction and appends the audit entry it describes.
func (s *Server) auditActionFn(ctx context.Context, fn func(pgx.Tx) (actor, action, target, detail string, err error)) error {
	tx, err := s.db.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	actor, action, target, detail, err := fn(tx)
	if err != nil {
		return err
	}
	if action == "" { // nothing to record (rate limited failures)
		return tx.Commit(ctx)
	}
	if err := audit(ctx, tx, actor, action, target, detail); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// generatedPassword: 32 random characters plus one of each character
// class, so it meets any password policy short of a longer minimum.
func generatedPassword() string { return randToken(24) + "-aA7" }

// localAdd creates a local account with generated credentials and returns them.
func localAdd(ctx context.Context, tx pgx.Tx, name, role string) (string, error) {
	pw, secret := generatedPassword(), newTOTPSecret()
	tag, err := tx.Exec(ctx, `INSERT INTO local_admins(name, role, password_hash, totp_secret) VALUES ($1,$2,$3,$4) ON CONFLICT DO NOTHING`,
		name, role, hashPassword(pw), secret)
	if err == nil && tag.RowsAffected() == 0 {
		err = errors.New("account exists already")
	}
	if err != nil {
		return "", err
	}
	return credentials(name, role, pw, secret), nil
}

// localReset replaces password and TOTP secret and clears a lockout.
func localReset(ctx context.Context, tx pgx.Tx, name string) (string, error) {
	pw, secret := generatedPassword(), newTOTPSecret()
	var role string
	err := tx.QueryRow(ctx, `UPDATE local_admins SET password_hash=$2, totp_secret=$3, totp_last_step=0, session_gen=session_gen+1, failures=0, locked_until=NULL
		WHERE name=$1 RETURNING role`, name, hashPassword(pw), secret).Scan(&role)
	if errors.Is(err, pgx.ErrNoRows) {
		err = errors.New("account not found")
	}
	if err == nil {
		_, err = tx.Exec(ctx, `DELETE FROM local_login_failures WHERE name=$1`, name)
	}
	if err != nil {
		return "", err
	}
	return credentials(name, role, pw, secret), nil
}

func credentials(name, role, pw, secret string) string {
	return fmt.Sprintf("user:     %s\nrole:     %s\npassword: %s\nsecret:   %s\ntotp:     %s\n", name, role, pw, secret, totpURI(name, secret))
}

type rowsOne struct{ ok bool }

func (r rowsOne) RowsAffected() int64 {
	if r.ok {
		return 1
	}
	return 0
}

// ---- CLI ----

// LocalAdmin manages local admin accounts: add, reset, disable, enable, list.
// add and reset return a generated password and TOTP URI.
func LocalAdmin(ctx context.Context, databaseURL, op, name, role string) (string, error) {
	pc, err := pgxPoolConfig(databaseURL, 4)
	if err != nil {
		return "", err
	}
	db, err := newPool(ctx, pc)
	if err != nil {
		return "", err
	}
	defer db.Close()
	if err := migrate(ctx, db); err != nil {
		return "", err
	}
	if op != "list" && !localNameRe.MatchString(name) {
		return "", errors.New("name must match " + localNameRe.String())
	}
	if !slices.Contains(roles, role) {
		return "", errors.New("role must be admin, helpdesk or auditor")
	}
	tx, err := db.Begin(ctx)
	if err != nil {
		return "", err
	}
	defer tx.Rollback(ctx)
	var out, detail string
	var res interface{ RowsAffected() int64 }
	switch op {
	case "add":
		out, err = localAdd(ctx, tx, name, role)
		detail = "role " + role
		res = rowsOne{err == nil}
	case "reset":
		out, err = localReset(ctx, tx, name)
		res = rowsOne{err == nil}
	case "disable", "enable":
		res, err = tx.Exec(ctx, `UPDATE local_admins SET disabled=$2, session_gen=session_gen+1 WHERE name=$1`, name, op == "disable")
	case "list":
		rows, qerr := tx.Query(ctx, `SELECT name, role, disabled, coalesce(last_login::text,'never') FROM local_admins ORDER BY name`)
		if qerr != nil {
			return "", qerr
		}
		var b strings.Builder
		for rows.Next() {
			var n, rl, last string
			var dis bool
			if err := rows.Scan(&n, &rl, &dis, &last); err != nil {
				return "", err
			}
			fmt.Fprintf(&b, "%-20s %-8s disabled=%-5v last_login=%s\n", n, rl, dis, last)
		}
		return b.String(), rows.Err()
	default:
		return "", errors.New("operation must be add, reset, disable, enable or list")
	}
	if err != nil {
		return "", err
	}
	if res.RowsAffected() == 0 {
		return "", fmt.Errorf("%s: no change (user exists already or not found)", op)
	}
	if err := audit(ctx, tx, "cli", "local_admin."+op, name, detail); err != nil {
		return "", err
	}
	return out, tx.Commit(ctx)
}
